export interface ConnectorConfig {
  /** Slack Bot Token with chat:write scope. Expected env var: SLACK_BOT_TOKEN */
  slackBotToken: string
  /** Injected fetch for testing or customization. */
  fetch?: typeof fetch
}

export interface TwilioSmsPayload {
  MessageSid: string
  AccountSid: string
  From: string
  To: string
  Body: string
  NumMedia: string
  NumSegments: string
  [key: string]: string
}

export interface HandleResult {
  channel: string
  ts: string
  slackChannelId: string
}

const SALES_REGEX = /pricing|quote|demo/i
const SLACK_API_URL = 'https://slack.com/api/chat.postMessage'

function determineChannel(body: string): string {
  return SALES_REGEX.test(body) ? '#sales' : '#support'
}

export async function handle(payload: TwilioSmsPayload, config: ConnectorConfig): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.Body || typeof payload.Body !== 'string') {
    throw new Error('Missing required field: Body')
  }
  if (!payload.From || typeof payload.From !== 'string') {
    throw new Error('Missing required field: From')
  }

  const channel = determineChannel(payload.Body)
  const text = payload.Body

  const response = await fetchImpl(SLACK_API_URL, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ channel, text })
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at POST ${SLACK_API_URL}`)
  }

  const data = await response.json() as { ok: boolean; channel: string; ts: string }

  if (!data.ok) {
    throw new Error(`Slack API returned ok=false: ${JSON.stringify(data)}`)
  }

  return {
    channel,
    ts: data.ts,
    slackChannelId: data.channel
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, TwilioSmsPayload, ConnectorConfig } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = { slackBotToken: 'xoxb-test-token', fetch }
    const result = await handle(SOURCE_EXAMPLE as unknown as TwilioSmsPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.channel).toBe('#sales')
    expect(result.slackChannelId).toBe('C01JASD6802')
    expect(result.ts).toBe('1234567890.123456')
  })
})

describe('handle', () => {
  it('routes to #sales when Body matches pricing', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage' && req.json?.channel === '#sales'
        ? jsonResponse({ ok: true, channel: 'C01JASD680000001', ts: '1111111111.111111' }, 200)
        : jsonResponse({ error: 'unexpected' }, 500)
    )
    const payload: TwilioSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'I need pricing info'
    }
    const result = await handle(payload, { slackBotToken: 'xoxb-test', fetch })
    expect(result.channel).toBe('#sales')
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'I need pricing info' })
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-test')
  })

  it('routes to #sales when Body matches quote', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage' && req.json?.channel === '#sales'
        ? jsonResponse({ ok: true, channel: 'C01JASD6002', ts: '2222222222.222222' }, 200)
        : jsonResponse({ error: 'unexpected' }, 500)
    )
    const payload: TwilioSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Please send me a quote'
    }
    const result = await handle(payload, { slackBotToken: 'xoxb-test', fetch })
    expect(result.channel).toBe('#sales')
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'Please send me a quote' })
  })

  it('routes to #sales when Body matches demo (case insensitive)', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage' && req.json?.channel === '#sales'
        ? jsonResponse({ ok: true, channel: 'C01JASD6003', ts: '3333333333.333333' }, 200)
        : jsonResponse({ error: 'unexpected' }, 500)
    )
    const payload: TwilioSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Can I schedule a DEMO?'
    }
    const result = await handle(payload, { slackBotToken: 'xoxb-test', fetch })
    expect(result.channel).toBe('#sales')
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'Can I schedule a DEMO?' })
  })

  it('routes to #support when Body does not match', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage' && req.json?.channel === '#support'
        ? jsonResponse({ ok: true, channel: 'C01JASD7001', ts: '4444444444.444444' }, 200)
        : jsonResponse({ error: 'unexpected' }, 500)
    )
    const payload: TwilioSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Hello, I have a general question'
    }
    const result = await handle(payload, { slackBotToken: 'xoxb-test', fetch })
    expect(result.channel).toBe('#support')
    expect(calls[0].json).toEqual({ channel: '#support', text: 'Hello, I have a general question' })
  })

  it('throws when Body is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ...SOURCE_EXAMPLE, Body: undefined as unknown as string }
    await expect(handle(payload as unknown as TwilioSmsPayload, { slackBotToken: 'xoxb-test', fetch }))
      .rejects.toThrow('Missing required field: Body')
  })

  it('throws when From is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ...SOURCE_EXAMPLE, From: undefined as unknown as string }
    await expect(handle(payload as unknown as TwilioSmsPayload, { slackBotToken: 'xoxb-test', fetch }))
      .rejects.toThrow('Missing required field: From')
  })

  it('throws on non-2xx response from Slack', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'invalid_auth' }, 401))
    const payload: TwilioSmsPayload = { ...SOURCE_EXAMPLE, Body: 'pricing please' }
    await expect(handle(payload, { slackBotToken: 'xoxb-test', fetch }))
      .rejects.toThrow('Slack API error: 401 Unauthorized at POST https://slack.com/api/chat.postMessage')
    expect(calls[0].url).toBe('https://slack.com/api/chat.postMessage')
  })

  it('throws when Slack returns ok=false', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ ok: false, error: 'channel_not_found' }, 200))
    const payload: TwilioSmsPayload = { ...SOURCE_EXAMPLE, Body: 'pricing please' }
    await expect(handle(payload, { slackBotToken: 'xoxb-test', fetch }))
      .rejects.toThrow('Slack API returned ok=false')
  })

  it('uses injected fetch from config', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage'
        ? jsonResponse({ ok: true, channel: 'C01JASD6999', ts: '9999999999.999999' }, 200)
        : jsonResponse({ error: 'unexpected' }, 500)
    )
    const payload: TwilioSmsPayload = { ...SOURCE_EXAMPLE, Body: 'demo request' }
    await handle(payload, { slackBotToken: 'xoxb-injected', fetch })
    expect(calls.length).toBe(1)
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-injected')
  })
